/* Copyright © 2026 上海如静知华信息科技有限公司 · https://www.zhuatech.cn/ */package cn.zhuatech.airedteam.model;import jakarta.persistence.*;import java.time.Instant;@Entity@Table(name="campaign_audit",uniqueConstraints=@UniqueConstraint(name="uk_campaign_request",columnNames="request_id"))public class CampaignAudit{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="request_id",nullable=false,length=80)private String requestId;@Column(nullable=false,length=30)private String decision;@Column(nullable=false)private int riskScore;@Column(nullable=false)private int findingCount;@Column(nullable=false,length=500)private String summary;@Column(nullable=false,length=80)private String createdBy;@Column(nullable=false)private Instant createdAt;protected CampaignAudit(){}public CampaignAudit(String r,String d,int s,int f,String m,String b){requestId=r;decision=d;riskScore=s;findingCount=f;summary=m;createdBy=b;createdAt=Instant.now();}public Long getId(){return id;}public String getRequestId(){return requestId;}public String getDecision(){return decision;}public int getRiskScore(){return riskScore;}public int getFindingCount(){return findingCount;}public String getSummary(){return summary;}public String getCreatedBy(){return createdBy;}public Instant getCreatedAt(){return createdAt;}}
